// Shared paths for the browser-test fixtures generated by ./server.ts.
//
// The server writes a real, freshly signed SD-JWT VC and one provider bearer
// token to temporary files at startup; the Playwright tests read them to
// exercise the real validation and editor-write APIs. Keeping both out of the
// repository avoids committing a credential-looking artifact or a usable token
// while still running against the real server.

import { tmpdir } from 'node:os'
import { join } from 'node:path'

export const PID_CREDENTIAL_FIXTURE = join(tmpdir(), 'attestbook-e2e-pid-credential.txt')

/** Bearer token of the seeded `Example Issuer` provider, for editor writes. */
export const EDITOR_TOKEN_FIXTURE = join(tmpdir(), 'attestbook-e2e-editor-token.txt')

/** Bearer token of the seeded `Digital Identity Authority` provider. */
export const AUTHORITY_TOKEN_FIXTURE = join(tmpdir(), 'attestbook-e2e-authority-token.txt')

// Disposable browser-login credentials for the seeded e2e administrator. They
// exist only for these tests and are never a deployment or production secret.
export const E2E_ADMIN_USERNAME = 'e2e-admin'
export const E2E_ADMIN_PASSWORD = 'e2e-admin-password'
